module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
// compact group-of-4 encoder
wire [7:0] c;
assign c[0]=|a_i[3:0];   assign c[1]=|a_i[7:4];
assign c[2]=|a_i[11:8];  assign c[3]=|a_i[15:12];
assign c[4]=|a_i[19:16]; assign c[5]=|a_i[23:20];
assign c[6]=|a_i[27:24]; assign c[7]=|a_i[31:28];

wire n7 = ~c[7];
wire n6 = ~(c[7]|c[6]);
wire n5 = ~(c[7]|c[6]|c[5]);
wire n4 = ~(c[7]|c[6]|c[5]|c[4]);
wire n3 = n4 & ~c[3];
wire n2 = n4 & ~(c[3]|c[2]);
wire n1 = n4 & ~(c[3]|c[2]|c[1]);

wire [7:0] e;
assign e[0]=a_i[3]|a_i[2];   assign e[1]=a_i[7]|a_i[6];
assign e[2]=a_i[11]|a_i[10]; assign e[3]=a_i[15]|a_i[14];
assign e[4]=a_i[19]|a_i[18]; assign e[5]=a_i[23]|a_i[22];
assign e[6]=a_i[27]|a_i[26]; assign e[7]=a_i[31]|a_i[30];

wire [7:0] d;
assign d[0]=a_i[3] |(a_i[1] &~a_i[2]);  assign d[1]=a_i[7] |(a_i[5] &~a_i[6]);
assign d[2]=a_i[11]|(a_i[9] &~a_i[10]); assign d[3]=a_i[15]|(a_i[13]&~a_i[14]);
assign d[4]=a_i[19]|(a_i[17]&~a_i[18]); assign d[5]=a_i[23]|(a_i[21]&~a_i[22]);
assign d[6]=a_i[27]|(a_i[25]&~a_i[26]); assign d[7]=a_i[31]|(a_i[29]&~a_i[30]);

wire [5:0] chosen;
assign chosen[5] = ~(n1 & ~c[0]);
assign chosen[4] = ~n4;
assign chosen[3] = (c[7]|c[6]) | (~c[5] & ~c[4] & (c[3]|c[2]));
assign chosen[2] = c[7] | (c[5]&~c[6]) | (c[3]&~c[4]&~c[6]) | (c[1]&~c[2]&~c[4]&~c[6]);
assign chosen[1] = e[7] | (e[6]&n7) | (e[5]&n6) | (e[4]&n5) |
                   (e[3]&n4) | (e[2]&n3) | (e[1]&n2) | (e[0]&n1);
assign chosen[0] = d[7] | (d[6]&n7) | (d[5]&n6) | (d[4]&n5) |
                   (d[3]&n4) | (d[2]&n3) | (d[1]&n2) | (d[0]&n1);

wire wen  = rst_n & valid_i;
wire keep = rst_n & ~valid_i;
always @(posedge clk) begin
    valid_o <= wen;
    y_o <= ({6{wen}} & chosen) | ({6{keep}} & y_o);
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
wire [31:0] s1 = a_i | {1'b0,  a_i[31:1]};
wire [31:0] s2 = s1  | {2'b0,  s1[31:2]};
wire [31:0] s4 = s2  | {4'b0,  s2[31:4]};
wire [31:0] s8 = s4  | {8'b0,  s4[31:8]};
wire [31:0] m  = s8  | {16'b0, s8[31:16]};

wire h0a = (m[31] | (m[29] & ~m[30])) | ((m[27] & ~m[28]) | (m[25] & ~m[26]));
wire h0b = ((m[23] & ~m[24]) | (m[21] & ~m[22])) | ((m[19] & ~m[20]) | (m[17] & ~m[18]));
wire h0c = ((m[15] & ~m[16]) | (m[13] & ~m[14])) | ((m[11] & ~m[12]) | (m[9] & ~m[10]));
wire h0d = ((m[7] & ~m[8]) | (m[5] & ~m[6])) | ((m[3] & ~m[4]) | (m[1] & ~m[2]));
wire h1a = (m[30] | (m[26] & ~m[28])) | ((m[22] & ~m[24]) | (m[18] & ~m[20]));
wire h1b = ((m[14] & ~m[16]) | (m[10] & ~m[12])) | ((m[6] & ~m[8]) | (m[2] & ~m[4]));

wire [5:0] chosen;
assign chosen[5] = m[0];
assign chosen[4] = m[16];
assign chosen[3] = m[24] | (m[8] & ~m[16]);
assign chosen[2] = (m[28] | (m[20] & ~m[24])) | ((m[12] & ~m[16]) | (m[4] & ~m[8]));
assign chosen[1] = h1a | h1b;
assign chosen[0] = (h0a | h0b) | (h0c | h0d);

wire wen  = rst_n & valid_i;
wire keep = rst_n & ~valid_i;
always @(posedge clk) begin
    valid_o <= wen;
    y_o <= ({6{wen}} & chosen) | ({6{keep}} & y_o);
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
// upper/lower 16 handled independently, then selected by hi16
wire [15:0] au = a_i[31:16];
wire [15:0] al = a_i[15:0];

wire [15:0] pu1 = au  | {1'b0, au[15:1]};
wire [15:0] pu2 = pu1 | {2'b0, pu1[15:2]};
wire [15:0] pu4 = pu2 | {4'b0, pu2[15:4]};
wire [15:0] mu  = pu4 | {8'b0, pu4[15:8]};

wire [15:0] pl1 = al  | {1'b0, al[15:1]};
wire [15:0] pl2 = pl1 | {2'b0, pl1[15:2]};
wire [15:0] pl4 = pl2 | {4'b0, pl2[15:4]};
wire [15:0] ml  = pl4 | {8'b0, pl4[15:8]};

wire hu = mu[0];
wire hl = ml[0];

wire [3:0] iu, il;
assign iu[3] = mu[8];
assign iu[2] = mu[12] | (mu[4] & ~mu[8]);
assign iu[1] = mu[14] | (mu[10]&~mu[12]) | (mu[6]&~mu[8]) | (mu[2]&~mu[4]);
assign iu[0] = mu[15] | (mu[13]&~mu[14]) | (mu[11]&~mu[12]) | (mu[9]&~mu[10]) |
               (mu[7]&~mu[8]) | (mu[5]&~mu[6]) | (mu[3]&~mu[4]) | (mu[1]&~mu[2]);
assign il[3] = ml[8];
assign il[2] = ml[12] | (ml[4] & ~ml[8]);
assign il[1] = ml[14] | (ml[10]&~ml[12]) | (ml[6]&~ml[8]) | (ml[2]&~ml[4]);
assign il[0] = ml[15] | (ml[13]&~ml[14]) | (ml[11]&~ml[12]) | (ml[9]&~ml[10]) |
               (ml[7]&~ml[8]) | (ml[5]&~ml[6]) | (ml[3]&~ml[4]) | (ml[1]&~ml[2]);

wire [5:0] chosen;
assign chosen[5] = hu | hl;
assign chosen[4] = hu;
assign chosen[3:0] = hu ? iu : il;

wire wen  = rst_n & valid_i;
wire keep = rst_n & ~valid_i;
always @(posedge clk) begin
    valid_o <= wen;
    y_o <= ({6{wen}} & chosen) | ({6{keep}} & y_o);
end
endmodule

module priority32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);
wire [15:0] q;
