wire h0c = ((a_i[15] & ~m[16]) | (a_i[13] & ~m[14])) | ((a_i[11] & ~m[12]) | (a_i[9] & ~m[10]));
wire h0d = ((a_i[7] & ~m[8]) | (a_i[5] & ~m[6])) | ((a_i[3] & ~m[4]) | (a_i[1] & ~m[2]));
